<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$pdo=db();$selected=normalize_class_name((string)($_GET['kelas']??''));$sql="SELECT u.id,u.username,u.email,u.full_name,u.phone,u.address,u.is_active,u.last_login_at,s.nama_lengkap child_name,s.nis,s.kelas,s.level,l.status link_status FROM users u LEFT JOIN parent_student_links l ON l.parent_id=u.id AND l.status='active' LEFT JOIN students s ON s.id=l.student_id WHERE u.role='orang_tua'";$params=[];if($selected){$sql.=' AND s.kelas=?';$params[]=$selected;}$sql.=' ORDER BY u.full_name';$stmt=$pdo->prepare($sql);$stmt->execute($params);$parents=$stmt->fetchAll();$pageTitle='Monitoring Orang Tua';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Akun Wali</p><h1 class="page-title">Monitoring Orang Tua</h1><p class="page-description">Periksa hubungan Orang Tua–anak, kelas anak, aktivitas login, dan biodata.</p></div><span class="badge badge-blue"><?= count($parents) ?> Orang Tua</span></div><section class="card" style="margin-bottom:20px"><h2 class="card-title">Pilih Kelas Anak</h2><div class="class-buttons"><a class="class-button <?= !$selected?'active':'' ?>" href="<?= url('admin/parents.php') ?>">Semua</a><?php foreach(all_class_names() as $class):?><a class="class-button <?= $selected===$class?'active':'' ?>" href="<?= url('admin/parents.php?kelas='.$class) ?>"><?= $class ?></a><?php endforeach;?></div></section><section class="card"><div class="filter-row"><input class="input" data-search-table="#parents-table" placeholder="Cari Orang Tua, anak, kelas, atau NIS..."></div><div class="table-wrap"><table class="table" id="parents-table"><thead><tr><th>Orang Tua</th><th>Anak Terhubung</th><th>Kelas Anak</th><th>Biodata</th><th>Login Terakhir</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($parents as $parent):$complete=25+($parent['email']?25:0)+($parent['phone']?25:0)+($parent['address']?25:0);?><tr><td><span class="name"><?= e($parent['full_name']) ?></span><br><small class="muted"><?= e($parent['username']) ?><?= $parent['email']?' · '.e($parent['email']):'' ?></small></td><td><?php if($parent['child_name']):?><strong><?= e($parent['child_name']) ?></strong><br><small>NIS <?= e($parent['nis']) ?> · <?= e(level_name($parent['level'])) ?></small><?php else:?><span class="badge badge-yellow">Belum terhubung</span><?php endif;?></td><td><?php if($parent['kelas']):?><a class="btn btn-soft btn-sm" href="<?= url('admin/students-classes.php?kelas='.e($parent['kelas'])) ?>">Kelas <?= e($parent['kelas']) ?></a><?php else:?><span class="badge badge-gray">Belum tersedia</span><?php endif;?></td><td><strong><?= $complete ?>%</strong><div class="progress"><span style="width:<?= $complete ?>%"></span></div></td><td><?= e(format_date_id($parent['last_login_at'],true)) ?></td><td><span class="badge <?= $parent['is_active']?'badge-green':'badge-red' ?>"><?= $parent['is_active']?'Aktif':'Nonaktif' ?></span></td><td><details><summary class="btn btn-blue btn-sm">Kelola Anak</summary><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax class="grid" style="min-width:260px;padding-top:10px"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= e($parent['id']) ?>"><div class="field"><label>NIS Anak</label><input class="input" name="nis" value="<?= e($parent['nis']) ?>"></div><button class="btn btn-primary btn-sm" name="action" value="link_child">Hubungkan/Pindahkan</button><?php if($parent['child_name']):?><button class="btn btn-danger btn-sm" name="action" value="unlink_child" data-confirm="Putuskan hubungan anak?">Putuskan</button><?php endif;?></form></details></td></tr><?php endforeach;?><?php if(!$parents):?><tr><td colspan="7"><div class="empty"><strong>Belum ada Orang Tua pada filter ini</strong>Pilih kelas lain atau buat akun Orang Tua.</div></td></tr><?php endif;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

